 public static function install(){global $wpdb;$t=self::table();if(''===$t||!method_exists($wpdb,'get_charset_collate'))return false;$exists=$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$t));if(null!==$exists){if($t!==$exists||!self::verify($t))return false;update_option(self::OPTION,self::VERSION,false);return true;}$lock='faluss_link_'.substr(hash('sha256',$wpdb->prefix),0,32);if(1!==(int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,%d)',$lock,10)))return false;try{if(null!==$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$t)))return false;$q='CREATE TABLE `'.$t.'` (`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,`faluss_id` char(36) NOT NULL,`cover_attachment_id` bigint(20) unsigned NULL,`avatar_visible` tinyint(1) NOT NULL,`name_weight` varchar(20) NOT NULL,`name_treatment` varchar(20) NOT NULL,`available` tinyint(1) NOT NULL,`bio_mode` varchar(20) NOT NULL,`announcement` varchar(120) NULL,`announcement_variant` varchar(20) NOT NULL,`social_links` longtext NOT NULL,`social_layout` varchar(20) NOT NULL,`link_style` varchar(20) NOT NULL,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `faluss_id_unique` (`faluss_id`)) ENGINE=InnoDB '.$wpdb->get_charset_collate();if(false===$wpdb->query($q)||!self::verify($t))return false;update_option(self::OPTION,self::VERSION,false);return true;}finally{$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));}}
